import tippy, { Instance as TippyInstance, Props as TippyProps } from 'tippy.js';
import { element } from 'tsx-vanilla';

import { SpellSchool } from '../../proto/common.js';
import { formatToCompactNumber } from '../../utils.js';
import { MetricsTotalBar, MetricsTotalBarProps } from './metrics_total_bar.js';

export interface MetricsCombinedTableEntry {
	name: string;
	value: number;
	percentage: number;
	average?: number;
}

export interface MetricsCombinedGroup {
	name?: string;
	cssClass?: string;
	totalPercentage: number;
	spellSchool?: SpellSchool | null;
	data: MetricsCombinedTableEntry[];
}

export interface MetricsCombinedTooltipTableProps {
	tooltipElement: HTMLElement;
	tooltipConfig?: Partial<TippyProps>;
	groups: MetricsCombinedGroup[];
	hasMetricBars?: boolean;
	headerValues?: Array<string | undefined>;
}

// Ported from the Cataclysm detailed-results UI: attaches a tippy tooltip to a
// cell that renders a breakdown table (e.g. hit/crit/glance/block counts, or
// miss/dodge/parry, or threat) on hover. Built imperatively to stay clear of
// tsx-vanilla's array/fragment handling.
export function MetricsCombinedTooltipTable({
	tooltipElement,
	tooltipConfig,
	headerValues,
	groups,
	hasMetricBars = true,
}: MetricsCombinedTooltipTableProps): TippyInstance | undefined {
	const displayGroups = groups.filter(group => group.data.some(d => d.value)).map(group => ({ ...group, data: group.data.filter(d => d.value) }));

	if (!displayGroups.length) {
		return undefined;
	}

	const hasAverageColumn = displayGroups.some(group => group.data.some(d => typeof d.average === 'number'));

	const headerRow = (<tr className="metrics-table-header-row"></tr>) as HTMLElement;
	headerRow.appendChild(<th className="metrics-table-header-cell">{headerValues?.[0] || 'Type'}</th>);
	headerRow.appendChild(<th className="metrics-table-header-cell">{headerValues?.[1] || 'Count'}</th>);
	if (hasAverageColumn) {
		headerRow.appendChild(<th className="metrics-table-header-cell">{headerValues?.[2] || 'Average'}</th>);
	}

	const tbody = (<tbody className="metrics-table-body"></tbody>) as HTMLElement;
	displayGroups.forEach(group => {
		const maxValue = Math.max(...group.data.map(d => d.value));
		const columnCount = group.data.some(d => typeof d.average === 'number') ? 3 : 2;

		if (group.name && displayGroups.length > 1) {
			const groupHeader = (<tr className={`metrics-table-group-header ${group.cssClass || ''}`}></tr>) as HTMLElement;
			const th = (<th className="text-start fw-normal">{group.name}</th>) as HTMLElement;
			th.setAttribute('colspan', String(columnCount));
			groupHeader.appendChild(th);
			tbody.appendChild(groupHeader);
		}

		[...group.data]
			.sort((a, b) => b.value - a.value)
			.forEach(entry => {
				const row = (<tr className={group.cssClass || ''}></tr>) as HTMLElement;
				row.appendChild(<td>{entry.name}</td>);

				const valueCell = (<td></td>) as HTMLElement;
				if (hasMetricBars) {
					valueCell.appendChild(
						MetricsTotalBar({
							spellSchool: group.spellSchool,
							percentage: group.totalPercentage > 0 ? (entry.percentage / group.totalPercentage) * 100 : 0,
							max: maxValue,
							total: entry.value,
							value: entry.value,
						}),
					);
				} else {
					valueCell.textContent = formatToCompactNumber(entry.value);
				}
				row.appendChild(valueCell);

				if (typeof entry.average === 'number') {
					row.appendChild(<td>{formatToCompactNumber(entry.average)}</td>);
				}
				tbody.appendChild(row);
			});
	});

	const content = (
		<table className="metrics-table">
			<thead className="metrics-table-header"></thead>
		</table>
	) as HTMLElement;
	content.querySelector('thead')!.appendChild(headerRow);
	content.appendChild(tbody);

	return tippy(tooltipElement, {
		placement: 'auto',
		theme: 'metrics-table',
		maxWidth: 'none',
		ignoreAttributes: true,
		...tooltipConfig,
		content,
	});
}
